import {startTutorial,needsTutorial} from './tutorial.js';
import {operationStories} from './operation-stories.js';
import {archetypes,operations,regions,newGame,describe,restoreGame,phase,forecast,provokesResponse,labels,secretRequirements,secretOperations,secretStatus,secretClue,businesses,assetOptions,opponents,threatPreview,responseOptions,responseBlocked,respond,operationDelay,regionalOutlook,crisisResponses,dilemmaOptions,resolveDilemma,recoveryAvailable,recoveryOptions,recoveryBlocked,recover,regionalRules,dilemmaBlocked,runSummary,turnBrief,optionInfo,chooseOption,jokerDefs,maxJokers,rollOptions,endTurn} from './game.js';
const $=s=>document.querySelector(s);let storageOK=true;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback;}catch{return fallback;}}
let legacy=read('ba-regional-record',{wins:0,runs:0});let saved=read('ba-regional-run',null);let s=restoreGame(saved)||newGame();let view='command',audio=false;let context;
const categories={economia:['↗','Econômicas'],politica:['♜','Políticas'],midia:['◉','Midiáticas'],tech:['◇','Tecnológicas'],saude:['✚','Saúde']};
const draftKindLabels={operation:'Operação',joker:'Carta permanente',asset:'Negócio',ally:'Aliança',rush:'Projeto',pass:'Aguardar'};
function save(){try{localStorage.setItem('ba-regional-run',JSON.stringify(s));localStorage.setItem('ba-regional-record',JSON.stringify(legacy));}catch{storageOK=false;}}
function sound(){if(!audio)return;try{context??=new AudioContext();const o=context.createOscillator(),g=context.createGain();o.type='sine';o.frequency.value=320;g.gain.setValueAtTime(.035,context.currentTime);g.gain.exponentialRampToValueAtTime(.001,context.currentTime+.15);o.connect(g).connect(context.destination);o.start();o.stop(context.currentTime+.15);}catch{audio=false;}}
const money=n=>`$${n.toFixed(1)}<small>B</small>`;
function metric(label,value,icon,color='green',suffix='%'){return `<div class="metric ${color}"><div class="metric-label"><span>${icon}</span>${label}</div><strong>${suffix==='B'?money(value):Math.round(value)+'<small>'+suffix+'</small>'}</strong><div class="meter"><i style="width:${suffix==='B'?Math.min(100,value*4):Math.max(0,value)}%"></i></div></div>`;}
// Simplified geographic outlines provide a functional region-selection map.
const land=['80,76 115,56 163,57 198,37 248,53 266,84 242,111 260,142 231,171 222,202 192,180 167,151 137,142 109,112','213,181 250,190 264,214 292,225 330,236 336,267 311,302 298,351 276,384 261,349 248,300 233,275 240,247','319,30 362,21 379,51 354,82 330,70','420,104 457,74 484,70 489,41 503,45 501,90 530,101 553,88 574,113 548,146 514,145 495,165 473,141 445,146','431,169 477,158 513,174 541,212 535,249 512,267 504,311 480,339 457,314 451,275 426,238 413,202','532,97 586,63 652,50 705,64 750,58 803,86 843,105 832,133 787,139 768,171 726,193 724,222 746,241 732,264 709,235 690,216 678,247 659,239 641,204 611,187 590,160 549,161','546,166 573,174 600,204 587,224 561,209','753,295 783,281 815,287 850,319 842,345 811,355 780,340 752,341 737,321','838,374 864,349 870,357 849,388','764,214 774,231 769,248 760,234','771,163 779,149 785,133 790,150 782,176','717,274 751,277 778,285 750,290','548,290 552,318 541,330 540,306'];
function map(){return `<div class="map"><div class="map-top"><span><i class="live-dot"></i> SATÉLITE GLOBAL <b>AO VIVO</b></span><span>GRID 23.55° S / 46.63° W</span></div><svg viewBox="0 0 940 430" role="img" aria-label="Mapa de regiões do mundo"><defs><pattern id="grid" width="47" height="43" patternUnits="userSpaceOnUse"><path d="M 47 0 L 0 0 0 43" fill="none" stroke="#1b2728" stroke-width=".6"/></pattern><pattern id="dots" width="6" height="6" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="#506058"/></pattern></defs><rect width="940" height="430" fill="url(#grid)"/><g fill="#192623" stroke="#44584c" stroke-width="1">${land.map(p=>`<polygon points="${p}"/>`).join('')}</g><g fill="url(#dots)">${land.map(p=>`<polygon points="${p}"/>`).join('')}</g><path d="M290 291 Q340 110 474 116 T724 240" fill="none" stroke="#bca76c" opacity=".3" stroke-dasharray="4 7"/>${s.regions.map((r,i)=>`<g style="--region-color:${r.heat>45?'var(--red)':'var(--green)'}" class="map-region ${s.selected===i?'selected':'locked-region'}" data-region="${i}" role="button" aria-disabled="${i!==s.territory}" tabindex="${i===s.territory?'0':'-1'}" aria-label="Selecionar ${r.name}, controle político ${Math.floor(r.control)}%, pressão ${Math.round(r.heat)}%"><circle cx="${r.x}" cy="${r.y}" r="20" class="halo"/><circle cx="${r.x}" cy="${r.y}" r="${5+r.heat/18}"/><text class="heat-label" x="${r.x}" y="${r.y-28}" text-anchor="middle">${r.heat>0?Math.round(r.heat)+'% PRESSÃO':''}</text><text class="map-state" x="${r.x}" y="${r.y+53}" text-anchor="middle">${i!==s.territory?'FORA DESTA CAMPANHA':r.crisisUntil>s.turn?'CRISE EM CURSO':r.asset?businesses[r.asset.type].name.toUpperCase():'SEM NEGÓCIO'}</text><text x="${r.x}" y="${r.y+37}" text-anchor="middle">${r.name.toUpperCase()}</text></g>`).join('')}</svg><div class="map-bottom"><span><i class="legend green"></i> Sua rede <i class="legend gold"></i> Alvo <i class="legend red"></i> Sob pressão</span><span>1 REGIÃO POR RUN</span></div></div>`;}
function archive(){return `<section class="full-panel"><span class="eyebrow">DOSSIÊ CONFIDENCIAL</span><h2>Registro de operações</h2><p>As decisões e consequências desta partida.</p>${s.history.map(h=>`<article class="archive-row"><b>${h.title}</b><p>${h.text}</p></article>`).join('')}</section>`;}
function render(){const a=archetypes.find(a=>a.id===s.archetype);$('#app').innerHTML=`<header><a class="brand" href="#" aria-label="Central de comando"><span class="brand-symbol">B<span>↘</span></span><span>BILLIONAIRE<small>APOCALYPSE</small></span></a><nav>${[['command','◈','Comando'],['archive','▤','Arquivo'],['legacy','♜','Partidas']].map(([id,icon,name])=>`<button data-view="${id}" class="${view===id?'active':''}">${icon} ${name}</button>`).join('')}</nav><div class="header-right"><button id="audio" aria-label="${audio?'Desativar':'Ativar'} som">${audio?'♪':'♫'} <span>SOM ${audio?'ON':'OFF'}</span></button><button id="help" aria-label="Como jogar">?</button><span class="secure"><i class="live-dot"></i> CONEXÃO SEGURA</span></div></header><main><div class="run-bar"><div class="run-identity"><img class="avatar" src="avatars/${a.id}.png" alt="Avatar de ${a.name}"><div><span class="eyebrow">${s.regions[s.territory].name.toUpperCase()} / DEMO REGIONAL</span><h1>${a.name}<span>PARTIDA ${String(legacy.runs+1).padStart(3,'0')}</span></h1></div></div><div class="turn-controls"><div class="quarter"><span class="eyebrow">${2027+Math.floor((s.turn-1)/4)} · T${(s.turn-1)%4+1}</span><span>Mês ${Math.min(3,s.actions+1)} de 3 · ${s.dilemma?'resolva a decisão pendente':'escolha uma das opções do mês'}</span></div></div></div><div class="metrics">${metric('Patrimônio',s.money,'$','gold','B')}${metric('Caos regional',s.chaos,'◉')}${metric('Influência local',s.regions[s.territory].influence,'♜')}${metric('Controle de mídia',s.media,'◌')}${metric('Capacidade tech',s.tech,'◇')}${metric('Exposição',s.exposure,'◎','red')}</div>${regionalCrisisPanel()}${worldBar()}${opponentOverview()}${decisionsPanel()}<div class="content ${view!=='command'?'single':''}">${view==='command'?command():view==='archive'?archive():legacyPanel()}</div><footer><span>B/A <b>CENTRAL DE COMANDO</b></span><span>${storageOK?'PROGRESSO SALVO LOCALMENTE':'ARMAZENAMENTO INDISPONÍVEL · PROGRESSO TEMPORÁRIO'} <button id="new-run">Nova partida ↗</button></span></footer></main>`;
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});document.querySelectorAll('[data-region]').forEach(b=>{const select=()=>{if(+b.dataset.region!==s.territory)return;s.selected=s.territory;save();render();};b.onclick=select;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};});document.querySelectorAll('[data-draft]').forEach(b=>b.onclick=()=>draftDialog(+b.dataset.draft));$('#new-run').onclick=()=>setup();$('#audio').onclick=()=>{audio=!audio;sound();render();};$('#help').onclick=help;bindDemo();document.querySelectorAll('[data-secret]').forEach(b=>b.onclick=()=>secretInfoDialog(b.dataset.secret));$('#view-report')?.addEventListener('click',quarterReport);$('.brand').onclick=e=>{e.preventDefault();view='command';render();};}
function pick(idx){
 const beforeTurn=s.turn;
 if(!chooseOption(s,idx))return false;
 finish();
 if(s.status==='playing'){if(s.turn>beforeTurn)quarterReport();else $('#modal').close();}
 return true;
}
function syncOptions(){
 const beforeTurn=s.turn;
 if(s.status==='playing'){if(s.actions>=3){if(!endTurn(s))s.options=[];}else rollOptions(s);}
 else s.options=[];
 finish();
 if(s.status==='playing'){if(s.turn>beforeTurn)quarterReport();else $('#modal').close();}
}
function finish(){sound();if(s.status!=='playing'&&!s.rewarded){legacy.runs++;if(s.status==='won')legacy.wins++;s.rewarded=true;}save();render();if(s.status!=='playing')result();}
function openModal(html){$('#modal').removeAttribute('aria-labelledby');$('#modal').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
render();if(!restoreGame(saved))setup();else if(s.status!=='playing')result();else if(needsTutorial()&&s.turn===1&&s.actions===0)startTutorial();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_game_state',description:'Consultar recursos, região e operações disponíveis da partida atual.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({status:s.status,turn:s.turn,money:s.money,chaos:s.chaos,exposure:s.exposure,region:s.regions[s.selected].name,world:s.world,pending:s.pending,options:s.options.map(c=>optionInfo(s,c)).map(o=>({kind:o.kind,id:o.id,name:o.name,cost:o.cost,blocked:o.blocked}))})})).catch(()=>{});}catch{}}

function worldBar(){
 const f=forecast(s),net=f.revenue-f.upkeep-f.sanctions;
 return `<section class="world-bar" aria-label="Resposta mundial"><div class="world-phase"><span class="radar-icon">◎</span><div><span class="eyebrow">RESPOSTA MUNDIAL</span><h2>${phase(s)}</h2></div></div><div class="world-gauge"><div><span>Alerta global</span><b>${Math.round(s.world.alert)}%</b></div><div class="meter"><i style="width:${s.world.alert}%"></i></div></div><div class="world-gauge investigation"><div><span>Investigação <small>100% = derrota</small></span><b>${Math.round(s.world.investigation)}%</b></div><div class="meter"><i style="width:${s.world.investigation}%"></i></div></div><div class="cash-forecast"><span>Fluxo previsto / trimestre</span><b class="${net<0?'negative':'positive'}">${net>=0?'+':'−'}$${Math.abs(net).toFixed(1)}B</b></div></section>`;
}
function regionPanel(){
 const r=s.regions[s.selected];
 return `<div class="region-panel"><div><span class="eyebrow">TEATRO DE OPERAÇÕES</span><h3>${r.name} <span>↗</span></h3></div><div class="region-stats">${[['Influência local',r.influence],['Controle político',r.control],['Pressão local',r.heat]].map(([n,v])=>`<div><span>${n}</span><b>${Math.round(v)}<small>/100</small></b><div class="meter"><i style="width:${v}%"></i></div></div>`).join('')}</div></div>`;
}
function draftIcon(info){
 if(info.kind==='operation')return categories[info.category][0];
 if(info.kind==='joker')return info.icon;
 if(info.kind==='asset')return '⌂';
 if(info.kind==='ally')return '♜';
 if(info.kind==='rush')return '◷';
 return '…';
}
function draftCard(choice,idx){
 const info=optionInfo(s,choice),effectText=Object.keys(info.effect).length?describe(info.effect):'';
 return `<button class="decision-card ${info.blocked?'unavailable':''}" data-draft="${idx}" aria-haspopup="dialog"><h3>${draftIcon(info)} ${info.name}</h3><p>${info.desc}</p>${effectText?`<span class="op-effects">${effectText}</span>`:''}<b>${info.cost?'$'+info.cost.toFixed(1)+'B':'Sem custo'} · ${draftKindLabels[info.kind]}</b><small>${info.blocked||'Ver detalhes ↗'}</small></button>`;
}
function draftSection(){
 return `<div class="section-heading operations-heading"><h2>Opções do mês</h2><span class="tag">MÊS ${Math.min(3,s.actions+1)} DE 3</span></div><div class="decision-grid draft-options">${s.options.map((choice,idx)=>draftCard(choice,idx)).join('')}</div>`;
}
function command(){
 const a=archetypes.find(a=>a.id===s.archetype);
 return `<section class="main-column"><div class="section-heading"><h2>Mapa de operações</h2><span class="tag">NEGÓCIOS E CRISES LOCAIS</span></div>${map()}${regionalOverview()}${regionPanel()}${businessPanel()}${secretPanel()}<div class="turn-intel"><div><span class="eyebrow">OBJETIVO DA DEMO</span><p>Alcance <b>100% de caos</b> em ${s.regions[s.territory].name}. O final depende das crises que você alimentar.</p></div><button id="view-report" ${s.report?'':'disabled'}>Último relatório ↗</button></div>${draftSection()}</section><aside><div class="commander-card"><img src="avatars/${a.id}.png" alt="${a.name}"><div class="commander-info"><span class="eyebrow">SEU PERFIL</span><h2>${a.name}</h2><p>${a.bonus}</p></div></div>${jokerPanel()}${characterPanel()}<div class="feed"><div class="feed-title"><h3>Notícias e consequências</h3></div><div aria-live="polite">${s.history.slice(0,4).map(h=>`<article class="feed-item ${h.type}"><div class="feed-meta">TRIMESTRE ${h.turn}</div><h4>${h.title}</h4><p>${h.text}</p></article>`).join('')}</div></div></aside>`;
}
function jokerPanel(){
 return `<section class="secret-panel"><div><span class="eyebrow">CARTAS PERMANENTES</span><h3>${s.jokers.length?`${s.jokers.length} de ${maxJokers}`:'Nenhuma carta adquirida'}</h3></div>${s.jokers.length?s.jokers.map(j=>{const def=jokerDefs.find(d=>d.id===j.id);return `<article class="ally"><b>${def.icon} ${def.name}</b><p>${def.desc}</p></article>`;}).join(''):'<p>Cartas permanentes aparecem entre as opções do mês e combinam com operações futuras do mesmo tipo.</p>'}</section>`;
}
function quarterReport(){
 const report=s.report;if(!report)return;const brief=report.brief||turnBrief(s);
 const delta=(key)=>{const d=report.after[key]-report.before[key];return `<b class="${key==='chaos'||key==='money'?d>=0?'positive':'negative':d>0?'negative':'positive'}">${d>0?'+':''}${d.toFixed(1)}${key==='money'?'B':'%'}</b>`;};
 openModal(`<div class="modal-heading"><span class="eyebrow">RELATÓRIO DE INTELIGÊNCIA / T${report.turn}</span><button id="close-report" aria-label="Fechar relatório">✕</button></div><h2>Resultados do trimestre</h2><p>${s.regions[s.territory].name} · ${report.phase}</p><div class="quarter-brief"><section><h3>O que suas decisões provocaram</h3>${brief.consequences.length?brief.consequences.map(h=>`<article><b>${h.title}</b><p>${h.text}</p></article>`).join(''):'<p>Nenhuma operação ou contramedida foi concluída neste fechamento.</p>'}</section><section><h3>O que os adversários preparam</h3>${brief.threats.length?brief.threats.map(p=>`<article><b>${p.name} · T${p.due}</b><p>Após ${p.source}: ${p.effect}.${p.decision?' Você já registrou uma resposta.':''}</p></article>`).join(''):'<p>Nenhuma medida tem prazo anunciado neste fechamento.</p>'}</section><section><h3>O que você pode avaliar agora</h3>${brief.opportunities.length?brief.opportunities.map(t=>`<p>${t}</p>`).join(''):'<p>Confira o negócio, a reserva e os projetos antes de escolher a próxima operação.</p>'}</section></div><h3>Balanço do trimestre</h3><div class="report-deltas">${[['money','Patrimônio'],['chaos','Caos'],['exposure','Exposição'],['investigation','Investigação']].map(([key,title])=>`<div><span>${title}</span>${delta(key)}</div>`).join('')}</div><details><summary>Ver registro completo do trimestre</summary><div class="report-entries">${report.entries.map(h=>`<article class="report-entry ${h.type}"><span>${h.type==='danger'?'!':h.type==='positive'?'↗':'◷'}</span><div><h3>${h.title}</h3><p>${h.text}</p></div></article>`).join('')}</div></details><div class="report-footer"><p>${s.pending.filter(p=>p.kind==='response').length} contramedidas ainda em preparação.</p><button class="primary" id="continue-turn">Planejar trimestre ${s.turn} →</button></div>`);
 $('#close-report').onclick=$('#continue-turn').onclick=()=>$('#modal').close();
}

function operationDetails(o,info){
 const region=s.regions[s.selected],good=[],bad=[];
 for(const [key,value] of Object.entries(info.effect)){
  const immediate=['exposure','investigation'].includes(key)||(o.id==='ipo'&&key==='money');
  const text=`${describe({[key]:value})} · ${immediate?'imediato':'no T'+(s.turn+operationDelay(s,o)+(o.id==='acquisition'&&key==='income'?1:0))}`;
  ((['exposure','investigation'].includes(key)?value<0:value>0)?good:bad).push(text);
 }
 if(info.effect.politics>0)good.push(`A influência política também gera +${(info.effect.politics*(region.corruption/100+.5)*(s.territory===0?1.25:1)).toFixed(1)}% de influência local e +${(info.effect.politics*.5).toFixed(1)}% de controle político no T${s.turn+1}.`);
 bad.unshift(`Custo de $${info.cost.toFixed(1)}B e 1 ação neste mês.`);
 const reactive=provokesResponse(s,o);
 if(reactive)bad.push('Helena Duarte seguirá os vínculos desta operação. Se já houver uma reportagem em andamento, a apuração será ampliada sem mudar o prazo.');
 if((info.effect.chaos||0)>=12||(reactive&&region.control>=35))bad.push('O Pacto de Estabilidade também pode preparar medidas contra esta região.');
 if(reactive)bad.push('Aumenta o alerta mundial, a pressão nesta região e a resistência a operações deste setor.');
 if(o.id==='acquisition')good.push(`Passa a controlar ${businesses[region.business].name.toLowerCase()}, com duas alternativas de uso; cada uma pode aparecer entre as opções do mês.`);
 if(o.id==='research'&&s.archetype==='visionario')good.push('Projeto de três trimestres. Uma opção de antecipar o lançamento pode aparecer entre as escolhas do mês, com 25% de risco de falha.');
 if(o.id==='campaign'&&s.archetype==='oligarca')good.push('Forma um aliado na região ou recupera 15 de lealdade de um aliado existente.');
 if(o.id==='offshore')bad.push('Não reduz a investigação nem cancela respostas em preparação.');
 if(o.id==='legal')bad.push('Não reduz a exposição, o alerta mundial nem cancela respostas em preparação.');
 const requirements=Object.entries(o.requires).map(([key,value])=>`${value}% de ${labels[key]} (atual: ${Math.round(['digital','sanitary'].includes(key)?s.regions[s.territory][key]:s[key])}%)`);
 requirements.push(...secretRequirements(s,o).map(r=>(r.met?'✓ ':'')+r.text));
 const cash=s.money-info.cost+(o.id==='ipo'?info.effect.money:0);
 return `<p class="operation-region">${region.name} · trimestre ${s.turn}</p><p class="operation-story">${operationStories[o.id]||o.desc}</p><div class="operation-facts"><div><span>Investimento</span><b>$${info.cost.toFixed(1)}B</b></div><div><span>Ações consumidas</span><b>1</b></div><div><span>Saldo após autorização</span><b class="${cash<=0?'negative':''}">$${cash.toFixed(1)}B</b></div></div><div class="operation-analysis"><section><h3>Benefícios previstos</h3><ul>${good.map(text=>`<li>${text}</li>`).join('')}</ul></section><section><h3>Custos e riscos</h3><ul>${bad.map(text=>`<li>${text}</li>`).join('')}</ul></section></div><p class="operation-requirements"><b>Requisitos:</b> ${requirements.length?requirements.join(' · '):'nenhum atributo mínimo'}.</p><p class="muted">Os valores consideram seu arquétipo, a resistência atual e as cartas permanentes adquiridas.</p><p class="bankruptcy-notice">Se o patrimônio chegar a $0B, a partida termina por falência.${cash<=0&&!info.blocked?' Esta operação consumirá todo o patrimônio disponível.':''}</p>`;
}
function draftDialog(idx){
 const choice=s.options[idx];if(!choice)return;
 const info=optionInfo(s,choice);
 const body=info.kind==='operation'?operationDetails(operations.find(o=>o.id===info.id),info):
  `<p class="operation-region">${s.regions[s.territory].name} · trimestre ${s.turn}</p><p class="operation-story">${info.desc}</p>${info.cost?`<div class="operation-facts"><div><span>Investimento</span><b>$${info.cost.toFixed(1)}B</b></div><div><span>Ações consumidas</span><b>1</b></div></div>`:''}<p class="bankruptcy-notice">Se o patrimônio chegar a $0B, a partida termina por falência.</p>`;
 openModal(`<div class="modal-heading"><span class="eyebrow">OPÇÃO DO MÊS · ${draftKindLabels[info.kind].toUpperCase()}</span><button id="close-operation" aria-label="Fechar detalhes">✕</button></div><h2 id="operation-title">${info.name}</h2>${body}<div class="operation-dialog-footer"><button class="text-button" id="cancel-operation">Voltar às opções</button><button class="primary" id="confirm-operation" ${info.blocked?'disabled':''}>${info.blocked||'Escolher esta opção'}</button></div>`);
 $('#modal').setAttribute('aria-labelledby','operation-title');
 $('#close-operation').onclick=$('#cancel-operation').onclick=()=>$('#modal').close();
 $('#confirm-operation').onclick=()=>{if(!pick(idx))draftDialog(idx);};
}
function secretInfoDialog(id){
 const idxInDraft=s.options.findIndex(c=>c.kind==='operation'&&c.id===id);
 if(idxInDraft>=0){draftDialog(idxInDraft);return;}
 const o=secretOperations.find(o=>o.id===id);if(!o)return;
 const reqs=secretRequirements(s,o).map(r=>(r.met?'✓ ':'')+r.text);
 openModal(`<div class="modal-heading"><span class="eyebrow">DOSSIÊ / OPERAÇÃO SECRETA</span><button id="close-operation" aria-label="Fechar">✕</button></div><h2>${o.name}</h2><p class="operation-story">${operationStories[id]||o.desc}</p><p class="operation-requirements"><b>Requisitos:</b> ${reqs.length?reqs.join(' · '):'nenhum'}.</p><p class="muted">Esta operação aparecerá entre as opções do mês quando os requisitos forem atendidos e houver caixa disponível.</p><div class="operation-dialog-footer"><button class="primary" id="cancel-operation">Voltar</button></div>`);
 $('#close-operation').onclick=$('#cancel-operation').onclick=()=>$('#modal').close();
}

function regionalOverview(){return `<div class="regional-overview"><p><b>${regionalRules[s.territory].title}</b>: ${regionalRules[s.territory].text}</p></div>`;}
function regionalCrisisPanel(){
 const r=s.regions[s.territory];
 return `<section class="regional-crisis-panel" aria-label="Condições do desfecho"><div><span class="eyebrow">CRISE EM ${r.name.toUpperCase()}</span><p>${regionalOutlook(s)}</p></div><div class="regional-indicators">${[['Controle político',r.control],['Fragilidade digital',r.digital],['Pressão sanitária',r.sanitary]].map(([label,v])=>`<div><span>${label}</span><strong>${Math.round(v)}%</strong><div class="meter"><i style="width:${v}%"></i></div></div>`).join('')}</div></section>`;
}
function secretPanel(){
 const r=s.regions[s.selected],discovered=secretOperations.find(o=>o.territory===s.selected&&r.unlocked.includes(o.id));
 return `<section class="secret-panel"><div><span class="eyebrow">OPERAÇÃO SECRETA / ${r.name.toUpperCase()}</span><h3>${discovered?'Oportunidade descoberta':'Rumores locais'}</h3></div>${discovered?`<p>Esta negociação é exclusiva de ${r.name}. Avalie suas condições atuais antes de comprometer recursos.</p><div class="secret-links"><button data-secret="${discovered.id}" aria-haspopup="dialog">${discovered.name}<span>${secretStatus(s,discovered)||(secretRequirements(s,discovered).every(x=>x.met)?'Ver dossiê ↗':'Requisitos pendentes')}</span></button></div>`:`<p>${secretClue(s)}</p><small>Informação incompleta · acompanhe as mudanças após seus investimentos.</small>`}</section>`;
}

function setup(){
 let chosen=s.archetype,territory=s.territory;
 openModal(`<div class="modal-heading"><span class="eyebrow">DEMO REGIONAL · ESCOLHA SEU PONTO DE PARTIDA</span>${saved?'<button id="close-modal" aria-label="Fechar">✕</button>':''}</div><h2>Escolha como construir seu grupo</h2><p>Adquira negócios, decida como utilizá-los e antecipe as respostas de Helena Duarte e do Pacto de Estabilidade. A meta é 100% de caos na região escolhida. A demo termina com um desfecho moldado por suas decisões.</p><div class="archetypes demo-archetypes">${archetypes.map(a=>`<button data-arch="${a.id}" class="archetype ${chosen===a.id?'chosen':''}"><div class="portrait-wrap"><img src="avatars/${a.id}.png" alt="${a.name}"></div><small>${a.tag}</small><h3>${a.name}</h3><p>${a.desc}</p><b>${a.bonus}</b></button>`).join('')}</div><fieldset class="starting-regions"><legend>Onde você vai atuar nesta run?</legend><p>Você permanece nesta região até o fim da demo. Todos os caminhos de crise estão disponíveis em qualquer território.</p><div class="starting-region-grid">${regions.map((r,i)=>`<button type="button" data-start-region="${i}" aria-pressed="${i===territory}" class="${i===territory?'chosen':''}"><h3>${r.name}</h3><b>${businesses[r.business].name}</b><p>${businesses[r.business].desc}</p><b>${regionalRules[i].title}</b><p>${regionalRules[i].text}</p></button>`).join('')}</div></fieldset><div class="setup-bottom"><p>3 ações por trimestre · progresso salvo neste navegador.<br><small>Esta demo usa uma partida separada do protótipo anterior.</small></p><button class="primary" id="start">Iniciar demo →</button></div>${saved?'<p class="muted">Iniciar substitui a partida atual da demo.</p>':''}`);
 document.querySelectorAll('[data-arch]').forEach(b=>b.onclick=()=>{chosen=b.dataset.arch;document.querySelectorAll('[data-arch]').forEach(x=>x.classList.toggle('chosen',x===b));});
 document.querySelectorAll('[data-start-region]').forEach(b=>b.onclick=()=>{territory=+b.dataset.startRegion;document.querySelectorAll('[data-start-region]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b));});});
 $('#close-modal')?.addEventListener('click',()=>$('#modal').close());
 $('#start').onclick=()=>{s=newGame(chosen,territory);saved=s;view='command';save();$('#modal').close();render();if(needsTutorial())startTutorial();};
}
function legacyPanel(){return `<section class="full-panel"><span class="eyebrow">SESSÕES DA DEMO</span><h2>Partidas encerradas</h2><div class="legacy-stats"><div><strong>${legacy.runs}</strong><span>PARTIDAS</span></div><div><strong>${legacy.wins}</strong><span>VITÓRIAS</span></div></div><p>Os dois perfis começam com condições fixas. Experimente uma abordagem diferente na próxima partida.</p><p class="muted">Progresso armazenado apenas neste navegador.</p></section>`;}
function result(){
 const summary=runSummary(s);
 openModal(`<span class="eyebrow">${s.status==='won'?'DEMO CONCLUÍDA':'PARTIDA ENCERRADA'}</span><h2>${s.status==='won'?s.finale.title:'O plano foi interrompido'}</h2><p>${s.ending}</p>${s.status==='won'?`<div class="ending-evidence"><h3>Condições no encerramento</h3><p>${s.regions[s.territory].name} · caos ${Math.round(s.finale.snapshot.chaos)}% · controle político ${Math.round(s.finale.snapshot.control)}% · fragilidade digital ${Math.round(s.finale.snapshot.digital)}% · pressão sanitária ${Math.round(s.finale.snapshot.sanitary)}%</p>${s.finale.causes.map(c=>`<p><b>${c.title}</b> · ${Math.round(c.value)}%</p>`).join('')}<p>A campanha regional termina aqui. Experimente outra região ou outro caminho em uma nova run.</p></div>`:''}<div class="result-stats"><span>${s.turn} trimestres</span><span>${Math.round(s.chaos)}% de caos</span><span>${s.stats.assetChoices} decisões de negócios</span></div><p>Você enfrentou ${s.stats.threatsFaced} ameaças e neutralizou ${s.stats.threatsResolved}. ${s.archetype==='visionario'?`${s.stats.projectsRushed} projetos foram antecipados.`:'As alianças fizeram parte da proteção dos negócios.'}</p><div class="ending-evidence"><h3>Decisões que marcaram a run</h3><p class="muted">Até três escolhas distintas, selecionadas pelo impacto registrado nos recursos e nas crises.</p>${summary.decisions.length?summary.decisions.map(d=>`<article><b>T${d.turn} · ${d.title}</b><p>${d.text}</p></article>`).join(''):'<p>Não há decisões registradas nesta run. Partidas anteriores à atualização começam a registrar escolhas a partir de agora.</p>'}<h3>O que restou do grupo</h3><p>${summary.business}</p><p>${summary.ally}</p><h3>Uma próxima tentativa</h3><p>${summary.next}</p></div><button class="primary" id="retry">Experimentar outro plano →</button><button class="text-button" id="inspect">Revisar decisões</button>`);
 $('#retry').onclick=setup;$('#inspect').onclick=()=>{$('#modal').close();view='archive';render();};
}
function opponentOverview(){return `<section class="opponent-overview" aria-label="Seus adversários">${Object.entries(opponents).map(([id,o])=>{
 const p=s.pending.find(p=>p.kind==='response'&&p.opponent===id);
 return `<article class="opponent ${o.color} ${p?'mobilized':''}"><div class="opponent-person"><span class="opponent-emblem">${o.initials}</span><div><span class="eyebrow">${o.role}</span><h2>${o.name}</h2></div><span class="opponent-deadline">${p?`T${p.due} · ${p.due-s.turn} tri.`:'Observando'}</span></div><p>${s.rivals[id].lastMove}</p>${p?`<div class="opponent-target"><b>${s.regions[p.region].name}${p.crisis?' · '+crisisResponses[p.crisis]:''}</b><span>${describe(predictedThreat(p))}</span></div>`:`<p class="opponent-behavior">${o.desc}</p>`}<button data-opponent="${id}" class="opponent-button">${p?p.handled?'Revisar decisão':'Avaliar resposta':'Conhecer adversário'} ↗</button></article>`;
 }).join('')}</section>`;}
function predictedThreat(p){const e=threatPreview(s,p);return p.contested?Object.fromEntries(Object.entries(e).map(([k,v])=>[k,+(v*.5).toFixed(1)])):e;}
function opponentDialog(id){
 const o=opponents[id],p=s.pending.find(p=>p.kind==='response'&&p.opponent===id);
 openModal(`<div class="modal-heading"><span class="eyebrow">${o.role}</span><button id="close-opponent" aria-label="Fechar">✕</button></div><h2>${o.name}</h2><p>${o.desc}</p>${p?`<div class="threat-brief"><h3>${p.opponent==='journalist'?'Reportagem':p.crisis?crisisResponses[p.crisis]:'Votação de sanções'} no trimestre ${p.due}</h3><p><b>${s.regions[p.region].name}</b> · origem: ${p.source}, no T${p.originTurn}.</p><p>Consequência prevista: ${describe(predictedThreat(p))}.</p>${p.opponent==='coalition'&&s.regions[p.region].asset?`<p class="negative">${s.regions[p.region].business==='energy'&&s.regions[p.region].crisisUntil>=p.due?'A concessão de energia será retirada.':'O negócio poderá ficar suspenso por dois trimestres.'}</p>`:''}<p>${p.handled?'Sua decisão já foi registrada para esta ameaça.':'Você pode conter a ameaça ou aceitar a consequência para preservar recursos agora.'}</p></div><div class="decision-grid">${responseOptions(s,p).map(choice=>`<button class="decision-card" data-threat="${p.id}" data-choice="${choice.id}" ${responseBlocked(s,p,choice.id)?'disabled':''}><h3>${choice.name}</h3><p>${choice.desc}</p><b>$${choice.cost.toFixed(1)}B · ${choice.id==='accept'?'sem ação':'1 ação'}</b><small>${responseBlocked(s,p,choice.id)||'Escolher esta resposta'}</small></button>`).join('')}</div>`:`<div class="threat-brief"><h3>Comportamento conhecido</h3><p>${id==='journalist'?'Helena acompanha ofertas especulativas, vínculos políticos e o uso agressivo de negócios. Novas operações durante uma apuração aumentam a gravidade da mesma reportagem. Uma rede de emissoras pode adiar a publicação uma vez.':'O Pacto se mobiliza diante de crises, pressão intensa ou controle político concentrado. Uma crise energética pode custar sua concessão. Aliados leais do Oligarca atenuam perdas e podem conter a votação.'}</p><p>Quando houver uma ação em preparação, o alvo, o prazo e as opções de resposta aparecerão aqui.</p></div>`}`);
 $('#close-opponent').onclick=()=>$('#modal').close();
 document.querySelectorAll('[data-threat]').forEach(b=>b.onclick=()=>{if(respond(s,+b.dataset.threat,b.dataset.choice))syncOptions();});
}
function businessPanel(){
 const r=s.regions[s.selected],b=businesses[r.business],a=r.asset;
 return `<section class="business-panel"><div class="business-heading"><span class="op-icon">${b.icon}</span><div><span class="eyebrow">NEGÓCIO REGIONAL</span><h3>${b.name}</h3></div><span class="business-status">${a?a.suspendedUntil>s.turn?`Suspenso até T${a.suspendedUntil}`:'Sob seu controle':'Disponível para aquisição'}</span></div><p>${b.desc}</p><p class="muted">${a?`Decisões de uso (${assetOptions[a.type].map(o=>o.name).join(' · ')}) aparecem entre as opções do mês quando disponíveis.`:'A aquisição aparece entre as opções do mês quando houver caixa disponível.'}</p><p class="business-income">Receita operacional: +$${b.income.toFixed(1)}B/tri. ${a&&a.suspendedUntil>s.turn?'Recebimentos interrompidos durante a suspensão.':''}</p>${r.crisisUntil>s.turn?'<p class="regional-crisis">Protestos e interrupções de serviços nesta região.</p>':''}</section>`;
}
function characterPanel(){
 if(s.archetype==='visionario'){
  const p=s.pending.find(p=>p.kind==='project');
  return `<section class="character-mechanic"><span class="eyebrow">PROJETOS DA VISIONÁRIA</span><h3>${p?'Pesquisa em desenvolvimento':'Nenhum projeto em curso'}</h3><p>${p?`${s.regions[p.region].name} · conclusão no T${p.due}. ${p.rushed?'Lançamento antecipado: 25% de risco de falha.':'Uma opção de antecipar o lançamento pode aparecer entre as escolhas do mês.'}`:'Financiar pesquisa inicia um projeto de três trimestres.'}</p></section>`;
 }
 return `<section class="character-mechanic"><span class="eyebrow">REDE DO OLIGARCA</span><h3>Aliados e compromissos</h3><p>Campanhas formam alianças. Lealdade de 40 ou mais reduz as perdas de sanções e permite mobilizar o aliado. Renovar o compromisso pode aparecer entre as opções do mês.</p>${s.regions.map((r,i)=>r.ally?`<article class="ally"><b>${r.name}</b><span>Lealdade ${Math.round(r.ally.loyalty)}% · exigência no T${r.ally.demandDue}</span><div class="meter"><i style="width:${r.ally.loyalty}%"></i></div></article>`:'').join('')}</section>`;
}
function bindDemo(){
 $('#open-dilemma')?.addEventListener('click',dilemmaDialog);
 $('#open-recovery')?.addEventListener('click',recoveryDialog);
 document.querySelectorAll('[data-opponent]').forEach(b=>b.onclick=()=>opponentDialog(b.dataset.opponent));
}
function help(){
 openModal(`<span class="eyebrow">GUIA DA DEMO</span><h2>Planeje, explore e reaja</h2><ol><li>Escolha sua região ao iniciar a run; não será possível trocar durante a campanha. Adquira o negócio local para gerar renda. A companhia de energia, as emissoras e o centro de dados oferecem decisões diferentes.</li><li>Escolha como utilizar a empresa. Uma crise pode acelerar o caos, mas suspender receitas ou custar a concessão.</li><li>Acompanhe Helena Duarte e o Pacto de Estabilidade. Cada um informa seu alvo e prazo. Examine as alternativas antes de gastar suas três ações.</li><li>A Visionária pode antecipar pesquisas com risco. O Oligarca forma aliados que precisam de apoio para manter a lealdade.</li><li>Leia os rumores locais. As três operações secretas dependem de oportunidades específicas, que se tornam mais claras com seus investimentos.</li><li>Dilemas aparecem com a evolução de cada crise e exigem uma escolha antes do próximo fechamento. Uma saída de emergência permite vender o negócio ou ceder controle e influência, uma vez por run.</li><li>Influência local abre negociações e pode ser cedida por proteção. Pressão local reduz a eficácia e atrai fiscalização; mídia protege contra reportagens; tecnologia permite novas operações.</li><li>Vença com 100% de caos regional. Controle político, fragilidade digital e pressão sanitária em 70% ou mais definem crises no desfecho; crises simultâneas se combinam. Controle político em 100% leva a guerra civil. A capacidade tech do grupo desbloqueia operações; a fragilidade digital mede o dano à região. Patrimônio zerado ou exposição/investigação em 100% encerram a partida.</li></ol><button id="understood" class="primary">Voltar à partida</button><button id="replay-tutorial" class="text-button">Rever tutorial guiado</button>`);
 $('#understood').onclick=()=>$('#modal').close();$('#replay-tutorial').onclick=()=>{$('#modal').close();view='command';render();startTutorial();};
}

function decisionsPanel(){return `<section class="run-decisions">${s.dilemma?`<article><span class="eyebrow">DECISÃO PENDENTE · T${s.dilemma.turn}</span><h2>${s.dilemma.title}</h2><p>${s.dilemma.text}</p><button class="primary" id="open-dilemma">Decidir antes do fechamento →</button></article>`:''}${recoveryAvailable(s)?`<article><span class="eyebrow">RESERVA DE EMERGÊNCIA · UMA VEZ POR RUN</span><h2>Recuar para continuar</h2><p>Você pode sacrificar um negócio ou parte da sua influência para recuperar recursos. A saída não consome ação e precisa ser usada antes da derrota.</p><button id="open-recovery" class="primary">Avaliar saída de emergência →</button></article>`:''}</section>`;}
function dilemmaDialog(){
 const d=s.dilemma;if(!d)return;
 openModal(`<span class="eyebrow">${s.regions[s.territory].name} · T${d.turn}</span><h2>${d.title}</h2><p>${d.text}</p><p>${d.regional?'Evento exclusivo desta região, provocado pelo avanço do caos.':'Origem: '+labels[d.axis]+' em '+Math.round(d.value)+'%.'} A decisão não consome ação. O trimestre só avança após uma escolha.</p><div class="decision-grid">${dilemmaOptions(s).map(o=>`<button data-dilemma-choice="${o.id}" class="decision-card" ${dilemmaBlocked(s,o.id)?'disabled':''}><h3>${o.name}</h3><p>${describe(o.effect)}</p><b>$${o.cost.toFixed(1)}B · sem ação</b><small>${dilemmaBlocked(s,o.id)||'Confirmar escolha'}</small></button>`).join('')}</div><p class="bankruptcy-notice">Gastar todo o patrimônio encerra a run por falência.</p><button id="close-decision" class="text-button">Rever a região antes de decidir</button>`);
 $('#close-decision').onclick=()=>$('#modal').close();document.querySelectorAll('[data-dilemma-choice]').forEach(b=>b.onclick=()=>{if(resolveDilemma(s,d.id,b.dataset.dilemmaChoice)){$('#modal').close();finish();}});
}
function recoveryDialog(){
 openModal(`<span class="eyebrow">SAÍDA DE EMERGÊNCIA</span><h2>O que você aceita perder?</h2><p>Disponível com patrimônio de até $4B ou exposição/investigação de pelo menos 75%. Uma utilização por run, sem consumir ação.</p><div class="decision-grid">${recoveryOptions(s).map(o=>`<button class="decision-card" data-recovery="${o.id}" ${recoveryBlocked(s,o.id)?'disabled':''}><h3>${o.name}</h3><p>${o.desc}</p><small>${recoveryBlocked(s,o.id)||'Confirmar sacrifício e recuperar recursos'}</small></button>`).join('')}</div><button id="close-decision" class="text-button">Continuar sem usar a saída</button>`);
 $('#close-decision').onclick=()=>$('#modal').close();document.querySelectorAll('[data-recovery]').forEach(b=>b.onclick=()=>{if(recover(s,b.dataset.recovery))syncOptions();});
}
